    mad.lo.u32 %col, %block_y, %ntid.y, %tid_y;

    // -------------------------------------------------
    // Bounds check
    // -------------------------------------------------
    .reg .pred %p_row_ok, %p_col_ok, %p_compute;
    setp.ge.u32 %p_row_ok, %row, %M;   // row >= M ?
    not.pred %p_row_ok, %p_row_ok;    // row < M
    setp.ge.u32 %p_col_ok, %col, %N;   // col >= N ?
    not.pred %p_col_ok, %p_col_ok;    // col < N
    and.pred %p_compute, %p_row_ok, %p_col_ok;
    @!%p_compute bra DONE;

