    // Compute base pointers for this row/col
    // -------------------------------------------------
    // A: row * K
    // B: col (will be added per k)
    .reg .u64 %a_row_ptr, %b_col_ptr, %c_elem_ptr;
    .reg .u32 %row_K, %k_N;
