    mul.wide.u32 %a_row_ptr, %a_row_ptr, 2;
    mul.wide.u32 %b_col_ptr, %b_col_ptr, 2;
    add.u64 %a_row_ptr, %a_row_ptr, %A;      // &A[row,0]
    // c element pointer
    mul.wide.u32 %c_elem_ptr, %row, %N;
    add.u32 %c_elem_ptr, %c_elem_ptr, %col;
    mul.wide.u32 %c_elem_ptr, %c_elem_ptr, 2;
    add.u64 %c_elem_ptr, %c_elem_ptr, %C;    // &C[row,col]

    // -------------------------------------------------
    // Accumulator (float32)
    // -------------------------------------------------
    .reg .f32 %acc;
    mov.f32 %acc, 0f0;

    // -------------------------------------------------
    // Loop over K dimension
    // -------------------------------------------------
    .reg .u32 %k;
    mov.u32 %k, 0;
LOOP_K:
    setp.ge.u32 %p_done, %k, %K;
    @%p_done bra END_LOOP;

    // Load A[row, k] (fp16)
    .reg .b16 %a_half;
    .reg .u64 %a_addr;
