    .reg .u64 %b_addr;
    // compute offset = k * N + col
    mul.wide.u32 %b_addr, %k, %N;              // k * N (elements)
    add.u32 %b_addr, %b_addr, %col;            // +col
    mul.wide.u32 %b_addr, %b_addr, 2;          // *2 (bytes)
    add.u64 %b_addr, %b_addr, %B;              // &B[k,col]
    ld.global.nc.b16 %b_half, [%b_addr];

