    .reg .f32 %a_f, %b_f;
    cvt.rn.f32.f16 %a_f, %a_half;
    cvt.rn.f32.f16 %b_f, %b_half;

    // acc += a_f * b_f
    fma.rn.f32 %acc, %a_f, %b_f, %acc;

    // k++
    add.u32 %k, %k, 1;
    bra LOOP_K;
END_LOOP:

    // -------------------------------------------------
    // Convert accumulator to fp16 and store
    // -------------------------------------------------
    .reg .b16 %c_half;
    cvt.rn.f16.f32 %c_half, %acc;
    st.global.nc.b16 [%c_elem_ptr], %c_half;

